#define FILE_DELETE_DELAY ((time_t)5)

int main(void) {
    /* 2100-07-04 00:00:00 UTC, well beyond 2^31 so truncation would show */
    time_t ttNow = (time_t)4118083200LL;
    time_t time_to_delete = (time_t)4118083190LL;
    const char *name = "gone.log";
    int is_file = 1;

    /* plugins/imfile/imfile.c: detect_updates, first DBGPRINTF (candidate) */
    printf("imfile-unlink: ");
    printf("detect_updates obj gone away, unlinking: "
           "'%s', ttDelete: %"PRId64"s, ttNow:%"PRId64" isFile: %d\n",
           name, (int64_t) ttNow - (time_to_delete + FILE_DELETE_DELAY),
           (int64_t) ttNow, is_file);

    /* plugins/imfile/imfile.c: detect_updates, second DBGPRINTF (candidate) */
    printf("imfile-keep: ");
    printf("detect_updates obj gone away, keep '%s' "
           "open: %"PRId64"/%"PRId64"/%"PRId64"s!\n",
           name, (int64_t) time_to_delete, (int64_t) ttNow,
           (int64_t) ttNow - time_to_delete);

    /* contrib/mmkubernetes/mmkubernetes.c: queryKB "Waited" (candidate) */
    {
        time_t now = (time_t)4118083000LL; /* elapsed time, > 2^31 */
        int busyRetryInterval = 30;
        const char *url = "https://kube.local/api";
        printf("mmk-waited: ");
        printf("mmkubernetes: Waited [%"PRId64"] of [%d] seconds for "
               "the requested url [%s]\n",
               (int64_t) now, busyRetryInterval, url);
    }
    return 0;
}

